class NotionMCPClient {
  state: MCPClientState = {
    connected: false,
    authenticated: false,
    sessionId: null,
    accessToken: null,
    mcpUrl: null,
  };

  private messageId = 0;
  private sessionId: string | null = null;
  private _accessToken: string | null = null;
  private _tools: MCPTool[] = [];
