    if (filter && typeof filter === "object" && !("operator" in filter)) {
      warnings.push(
        '⚠ notion-query-meeting-notes: Empty filter {} will fail. Use {"filter": {"operator": "and", "filters": []}}.',
      );
    }
  }

  return warnings;
}

