}

interface NotionUserInfo {
  workspaceId: string;
  workspaceName: string;
  workspaceIcon?: string;
  botId: string;
  ownerEmail?: string;
  ownerName?: string;
}

interface AuthStatus {
  authenticated: boolean;
  workspaceName?: string;
  message: string;
}

